contentRule.content:
$..param
@js:
a=baseUrl.replace(/.*post_id=(.*?)&.*/,'{"headers":{"Referer":"https://nekoyo.co"},"method": "GET"}');
b=baseUrl.replace(/.*post_id=(.*?)&.*/,'{"headers":{"Referer":"https://nekoyo.co/anime/info/$1/player"},"method": "GET"}');
s={"headers":{"Referer":"https://nekoyo.co"}}
var th1 = /cdn.*?jpg/g;
var matches = result.match(th1);
var matchs = result.match(/path.*(http.*m3u8)/);

if (matches) {
    var imgTags = matches.map(function(x) {
        return '<img src="https://' + x + ',' + a + '">';
    }).join("\n"); 
    //java.log(imgTags);
} else if (matchs) {
	if (book['durChapterIndex'] == chapter['index']){
    c = matchs[1] + ',' + b;
    java.startBrowser(c, title);
    java.toast('正在加载视频\n视频功能还未完善');
    '【刷新正文】播放\n直链:\n' + c;
    }
} else {
    content = java.base64Decode(result);
}

